  return (
    <div className="App">
      <header className="App-header">
        {/* <NavigationBar/>  */}
            <Router>
      <nav>
        <ul>
          <li><Link to="/link">Link Account</Link></li>
          <li style={{display: 'inline',  marginRight: '10px'}}><Link to="/games">Games</Link></li>
          <li style={{display: 'inline',  marginRight: '10px'}}><Link to="/about">About COMS</Link></li>
          <li style={{display: 'inline',  marginRight: '10px'}}><Link to="/profile">Profile</Link></li>
        </ul>
      </nav>

      <Routes>
        <Route path="/link" element={<Home/>}/>
      </Routes>
    </Router>
      </header> 
    </div>
  );
}

export default App;
